namespace D2Common::Drlg::Maze {

// DRLG maze generation: for special-room levels (selected by nLevelType, mapping to a base preset-file offset), randomly marks a fraction (~roomCount/5, min 2) of the level's RoomEx entries with a chosen preset variant. Uses the level's LCG seed to Fisher-Yates shuffle a 15-entry index table, then walks RoomEx rooms matching a target file index and rewrites their room-data fields (sets bit 2, replaces the file id, sets field[1]=-1). Skips eD2LevelId 8 (Den of Evil), hence the name. Mutates pLevel->sSeed as it consumes randoms.
void __fastcall ForAllButDenOfEvil(D2DrlgLevelStrc * pLevel) {
    D2RoomExStrc* pDVar1;
    D2DrlgPresetRoomStrc* pDVar2;
    int nSwapTemp;
    int nShufflePos;
    int aShuffleTable[16];
    int nFirstFileOffset;
    switch (pLevel->nLevelType) {
      case 3:
        nFirstFileOffset = 0x34;
      break;
      case 4:
        nFirstFileOffset = 0x6c;
      break;
      default:
        return;
      case 7:
        nFirstFileOffset = 0xa7;
      break;
      case 8:
        nFirstFileOffset = 0xcd;
      break;
      case 10:
        nFirstFileOffset = 0x101;
      break;
      case 0xd:
        nFirstFileOffset = 0x12d;
      break;
      case 0x11:
        nFirstFileOffset = 0x19d;
      break;
      case 0x16:
        nFirstFileOffset = 0x2f1;
      break;
      case 0x18:
        nFirstFileOffset = 0x298;
      break;
      case 0x19:
        nFirstFileOffset = 0x2c0;
    }

    if (pLevel->eD2LevelId == 8) {
      return;
    }

    aShuffleTable[8] = 8;
    D2SeedStrc DVar3 = D2_SEED_NEXT(pLevel->sSeed);
    pLevel->sSeed = DVar3;
    aShuffleTable[0xf] = DVar3.nSeedLow + (int)(((uint64_t)d2_bits_of(DVar3) & 0xffffffff) / 0xf) * -0xf;
    int nTargetCount = pLevel->nRoomExCount / 5 + 1;
    aShuffleTable[0] = 0;
    aShuffleTable[1] = 1;
    aShuffleTable[2] = 2;
    aShuffleTable[3] = 3;
    aShuffleTable[4] = 4;
    aShuffleTable[5] = 5;
    aShuffleTable[6] = 6;
    aShuffleTable[7] = 7;
    aShuffleTable[9] = 9;
    aShuffleTable[10] = 10;
    aShuffleTable[0xb] = 0xb;
    aShuffleTable[0xc] = 0xc;
    aShuffleTable[0xd] = 0xd;
    aShuffleTable[0xe] = 0xe;
    if (nTargetCount < 3) {
      nTargetCount = 2;
    }

    int nMaxTries = pLevel->nRoomExCount * 2;
    int nShuffleCount = 0xf;
    do {
      D2SeedStrc DVar4;
      DVar3 = D2_SEED_NEXT(pLevel->sSeed);
      pLevel->sSeed = DVar3;
      DVar4 = D2_SEED_NEXT(pLevel->sSeed);
      pLevel->sSeed = DVar4;
      nSwapTemp = nShuffleCount - 1;
      nShuffleCount = nSwapTemp;
      nShufflePos = aShuffleTable[DVar3.nSeedLow + (int)(((uint64_t)d2_bits_of(DVar3) & 0xffffffff) / 0xf) * -0xf];
      aShuffleTable[DVar3.nSeedLow + (int)(((uint64_t)d2_bits_of(DVar3) & 0xffffffff) / 0xf) * -0xf] = aShuffleTable[DVar4.nSeedLow + (int)(((uint64_t)d2_bits_of(DVar4) & 0xffffffff) / 0xf) * -0xf];
      aShuffleTable[DVar4.nSeedLow + (int)(((uint64_t)d2_bits_of(DVar4) & 0xffffffff) / 0xf) * -0xf] = nShufflePos;
      nShufflePos = aShuffleTable[0xf];
    } while (nSwapTemp);

    for (; nTargetCount && nMaxTries; nMaxTries--) {
      aShuffleTable[0xf] = aShuffleTable[nShufflePos] + nFirstFileOffset + 0xf;
      for (pDVar1 = pLevel->pRoomExFirst; pDVar1; pDVar1 = pDVar1->pRoomExNext) {
        pDVar2 = pDVar1->pRoomExData.pRoomExDataPreset;
        if (~(pDVar2->nFlags >> 1) & 1 && pDVar2->nLevelPrest == aShuffleTable[nShufflePos] + nFirstFileOffset) {
          pDVar2->nFlags |= 2;
          nTargetCount--;
          pDVar2->nLevelPrest = aShuffleTable[0xf];
          pDVar2->nPickedFile = -1;
          break;
        }
      }

      nShufflePos++;
      nSwapTemp = (int)((uint64_t)((int64_t)nShufflePos * 0x77777777) >> 0x20) - nShufflePos;
      nShufflePos += ((nSwapTemp >> 3) - (nSwapTemp >> 0x1f)) * 0xf;
    }
}

// Selects a random preset file index for a maze level using the level's seed and LvlPrest table.
// @sourcefile .\DRLG\Maze.cpp
int __stdcall DRLGMAZE_SelectRandomPresetFile(int nPresetFile, D2DrlgLevelStrc * pLevel, int * pState) {
    int* pSelectedOffset;
    D2DrlgLevelLinkNodeStrc* pNode;
    eLvlTypes nLevelType;
    if (nPresetFile != -1) {
      pState[1] = nPresetFile;
      return nPresetFile;
    }

    uint32_t nFileCount;
    nFileCount = ((int*)pState[2])[0x10];
    int nFirstFile;
    nFirstFile = *(int*)pState[2];
    int* nResult;
    nResult = (int*)(pLevel->nLevelType - 3);
    if (nResult >= (int*)0x21) {
      return (int)nResult;
    }

    nResult = (int*)(uint32_t)gaMazeLevelTypeCaseTable[pLevel->nLevelType + 1];
    switch ((uint32_t)gaMazeLevelTypeCaseTable[pLevel->nLevelType + 1]) {
      case 0:
        pSelectedOffset = (int*)0x34;
      break;
      case 0x1:
        pSelectedOffset = (int*)0x6c;
      break;
      case 0x2:
        pSelectedOffset = (int*)0xa7;
      break;
      case 0x3:
        pSelectedOffset = (int*)0xcd;
      break;
      case 0x4:
        pSelectedOffset = (int*)0x101;
      break;
      case 0x5:
        pSelectedOffset = (int*)0x12d;
      break;
      case 0x6:
        pSelectedOffset = (int*)0x19d;
      break;
      case 0x7:
        pSelectedOffset = (int*)0x1e1;
      break;
      case 0x8:
        pSelectedOffset = (int*)0x2f1;
      break;
      case 0x9:
        pSelectedOffset = (int*)0x298;
      break;
      case 0xa:
        pSelectedOffset = (int*)0x2c0;
      break;
      case 0xb:
        pSelectedOffset = (int*)0x344;
      break;
      case 0xc:
        pSelectedOffset = (int*)0x3ea;
      break;
      case 0xd:
        pSelectedOffset = (int*)0x422;
      break;
      case 0xe:
        pSelectedOffset = (int*)0x41c;
      break;
      case 0xf:
        return (int)nResult;
    }

    nResult = pSelectedOffset;
    if (nFirstFile <= (int)pSelectedOffset) {
      return (int)nResult;
    }

    nResult = pSelectedOffset + 4;
    if (nFirstFile >= (int)(pSelectedOffset + 4)) {
      return (int)nResult;
    }

    for (pNode = pLevel->pLevelLinkNodeFirst; pNode; pNode = pNode->pNext) {
      if (pNode->dwData0 == nFirstFile) {
        goto next_file;
      }
    }

    pNode = ((D2DrlgLevelLinkNodeStrc*)Fog::Memory::AllocServerMemory(pLevel->pDrlg->pMemoryPool, sizeof(D2DrlgLevelLinkNodeStrc), ".\\DRLG\\Maze.cpp", 0x780, 0));
    pNode->dwData2 = 0;
    pNode->pNext = 0;
    pNode->dwData0 = nFirstFile;
    pNode->dwData1 = nFileCount;
    nFileCount = D2Client::Archive::RANDOM_RandomNumberSelector(&pLevel->sSeed, nFileCount);
    pNode->dwData2 = nFileCount;
    pNode->pNext = pLevel->pLevelLinkNodeFirst;
    pLevel->pLevelLinkNodeFirst = pNode;
    next_file:
    nFirstFile = (pNode->dwData2 + 1) % pNode->dwData1;
    pNode->dwData2 = nFirstFile;
    pState[1] = nFirstFile;
    nResult = pState;
    return (int)nResult;
}

static void __stdcall InitAllRoomsEx(D2RoomExStrc * pRoomEx, D2DrlgLevelStrc * pLevel) {
    BOOL bSingleRoom;
    D2DrlgOrthStrc* pDVar2;
    D2DrlgPresetRoomStrc* pDVar1 = pRoomEx->pRoomExData.pRoomExDataPreset;
    D2DrlgMapStrc* pDrlgLevelSub1B0 = Preset::DRLGPRESET_AllocDrlgMap(pLevel, pDVar1->nLevelPrest, (D2DrlgCoordStrc*)&pRoomEx->sCoords, &pLevel->sSeed);
    DRLGMAZE_SelectRandomPresetFile(pDVar1->nPickedFile, pLevel, &pDrlgLevelSub1B0->nNumber);
    if (pRoomEx->sCoords.WorldSize.x < 0xd && pRoomEx->sCoords.WorldSize.y < 0xd) {
      bSingleRoom = 1;
    } else {
      bSingleRoom = 0;
    }

    D2RoomExStrc* pRoomEx_00 = Preset::BuildArea(pLevel, pDrlgLevelSub1B0, 0, bSingleRoom);
    for (pDVar2 = pRoomEx->pOrth; pDVar2; pDVar2 = pDVar2->pNext) {
      if (pDVar2->nType == 1) {
        DrlgRoom::DRLGROOMEX_AllocNodesForBothRoomEx(pRoomEx_00, pDVar2->pLink.pRoomEx, pDVar2->neDrlgDirection);
      }
    }

    DrlgRoom::DRLGROOMEX_FreeDrlgRoomEx(pRoomEx);
}

void __fastcall DRLGMAZE_InitializeLevel(D2DrlgLevelStrc * pLevel) {
    D2LvlMazeTxt* pLvlMazeTxt = DATATBLS::LvlTbls::TXT_LvlMaze_FindLineByLevelId(pLevel->eD2LevelId);
    pLevel->pDrlgLevelData.pTxtLvlMaze = pLvlMazeTxt;
    DRLGLEVEL_SetLevelSizeAndAlignVsDependentLevel(pLevel->pDrlg, pLevel);
}

// Top-level DRLG maze-level generator: builds the room layout for a maze-type D2 level. Allocates the level's root RoomEx (size/position from the level's preset DRLG data, centered in the level world rect) and adds it, then dispatches on nLevelType (and sometimes eD2LevelId) to the act/area-specific generator chain - e.g. Act1 Caves/Crypt/Jail/Catacombs, Act2 Sewer/Lair/Arcane/Tombs, Act3 Kurast/Durance/Sewers, Act5 Temple/IceCaves/Worldstone, Baal chamber - typically calling DRLGMAZE_BuildRoomGrid + ActualLevelGeneration then a per-area Replace/Roll pass. Patches fixed special rooms (e.g. Act3 sewer entry rooms 0x2c5..0x2ca to 0x2df.., ice-cave Frozen River/Drifter Cavern/Icy Cellar variants) by id. Applies barracks/river-of-flames/coordinate adjustment, then InitAllRoomsEx over every room. Halts via Fog ErrorManager on missing expected rooms or unknown level type. Returns a BOOL.
BOOL __fastcall DRLGMAZE_GenerateLevel(D2DrlgLevelStrc * pLevel) {
    D2DrlgPresetRoomStrc* pDVar1;
    uint32_t nVariant;
    BOOL bResult;
    eD2LevelId eLevelId;
    D2RoomExStrc* pRoomIter;
    D2RoomExStrc* pNextRoom;
    D2DrlgPresetRoomStrc* pDrifterCavernRoomData;
    D2DrlgPresetRoomStrc* pFrozenRiverRoomData;
    D2DrlgPresetRoomStrc* pIcyCellarRoomData;
    D2RoomExStrc* pSearchRoom;
    D2RoomExStrc* pRoomEx;
    pRoomEx = DrlgRoom::DRLGROOMEX_AllocRoomEx(pLevel, 2);
    D2LvlMazeTxt* pLvlMazeTxtLocal;
    pLvlMazeTxtLocal = pRoomEx->pLevel->pDrlgLevelData.pTxtLvlMaze;
    int nSizeX;
    nSizeX = pLvlMazeTxtLocal->SizeX;
    pRoomEx->sCoords.WorldSize.x = nSizeX;
    pRoomEx->sCoords.WorldSize.y = pLvlMazeTxtLocal->SizeY;
    pRoomEx->sCoords.WorldPosition.x = (pLevel->sCoordinatesAndSize.WorldSize.x - nSizeX) / 2 + pLevel->sCoordinatesAndSize.WorldPosition.x;
    pRoomEx->sCoords.WorldPosition.y = (pLevel->sCoordinatesAndSize.WorldSize.y - pRoomEx->sCoords.WorldSize.y) / 2 + pLevel->sCoordinatesAndSize.WorldPosition.y;
    DrlgRoom::AddRoomExToLevel(pLevel, pRoomEx);
    switch (pLevel->nLevelType) {
      case 3:
        /* Act 1 caves */ ActualLevelGeneration(pLevel);
      Act1::Caves(pLevel);
      break;
      case 4:
        ActualLevelGeneration(pLevel);
      Act1::Crypt(pLevel);
      break;
      default:
        {
          Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", (int32_t)(char*)Fog::Src::ErrorManager::GetInstructionPointer(), 0x883);
          exit(-1);
        }
      case 7:
        DRLGMAZE_BuildRoomGrid(2, pLevel);
      case 0x1c:
        ActualLevelGeneration(pLevel);
      break;
      case 8:
        DRLGMAZE_BuildRoomGrid(2, pLevel);
      ActualLevelGeneration(pLevel);
      Act1::Jail::RollRooms(pLevel);
      break;
      case 10:
        Act1::Catacombs::DRLGMAZE_ExpandCatacombsLevel(pLevel, (uint32_t)(pLevel->eD2LevelId == 0x22));
      ActualLevelGeneration(pLevel);
      Act1::Catacombs::DRLGMAZE_ReplaceCatacombsRooms(pLevel);
      break;
      case 0xd:
        DRLGMAZE_BuildRoomGrid(2, pLevel);
      ActualLevelGeneration(pLevel);
      Act2::Sewer::DRLGMAZE_GenerateSewerLevel(pLevel);
      break;
      case 0xe:

      case 0xf:

      case 0x17:
        DRLGMAZE_BuildRoomGrid(2, pLevel);
      break;
      case 0x11:
        /* Tombs */ if (pLevel->eD2LevelId == 0x3d) {
          pDVar1 = pRoomEx->pRoomExData.pRoomExDataPreset;
          pDVar1->nFlags |= 2;
          pDVar1->nLevelPrest = 0x1e0;
          pDVar1->nPickedFile = -1;
        } else {
          GenerateWolrdstoneAndTombs(pLevel);
          ActualLevelGeneration(pLevel);
          Act2::Tombs::ReplaceAreas(pLevel);
        }
      break;
      case 0x12:
        /* Lair */ DRLGMAZE_BuildRoomGrid(2, pLevel);
      ActualLevelGeneration(pLevel);
      Act2::Lair(pLevel);
      break;
      case 0x13:
        /* Arcane */ Act2::Arcane::RollArcaneTypePath(pLevel);
      Act2::Arcane::PickSummonerLocation(pLevel);
      break;
      case 0x16:
        /* Kurast */ DRLGMAZE_BuildRoomGrid(2, pLevel);
      ActualLevelGeneration(pLevel);
      Act3::Durance::ReplaceRooms(pLevel);
      break;
      case 0x18:
        DRLGMAZE_BuildRoomGrid(2, pLevel);
      ActualLevelGeneration(pLevel);
      Act3::DungeonRoll(pLevel);
      break;
      case 0x19:
        /* Act 3 sewers */ if (pLevel->eD2LevelId != 0x5c) {
          DRLGMAZE_BuildRoomGrid(2, pLevel);
          ActualLevelGeneration(pLevel);
          Act3::Sewers::DRLGMAZE_ReplaceSewerRooms(pLevel);
          break;
        }
      DRLGMAZE_BuildRoomGrid(5, pLevel);
      for (pRoomIter = pLevel->pRoomExFirst; pRoomIter; pRoomIter = pRoomIter->pRoomExNext) {
        pDVar1 = pRoomIter->pRoomExData.pRoomExDataPreset;
        if (~(pDVar1->nFlags >> 1) & 1 && pDVar1->nLevelPrest == 0x2c5) {
          pDVar1->nFlags |= 2;
          pDVar1->nLevelPrest = 0x2df;
          pDVar1->nPickedFile = -1;
          pSearchRoom = pLevel->pRoomExFirst;
          while (true) {
            if (!pSearchRoom) {
              Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", (int32_t)(char*)Fog::Src::ErrorManager::GetInstructionPointer(), 0x84a);
              exit(-1);
            }

            pDVar1 = pSearchRoom->pRoomExData.pRoomExDataPreset;
            if (~(pDVar1->nFlags >> 1) & 1 && pDVar1->nLevelPrest == 0x2c6) {
              break;
            }

            pSearchRoom = pSearchRoom->pRoomExNext;
          }

          pDVar1->nFlags |= 2;
          pDVar1->nLevelPrest = 0x2e0;
          pDVar1->nPickedFile = -1;
          pSearchRoom = pLevel->pRoomExFirst;
          while (true) {
            if (!pSearchRoom) {
              Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x84b);
              exit(-1);
            }

            pDVar1 = pSearchRoom->pRoomExData.pRoomExDataPreset;
            if (~(pDVar1->nFlags >> 1) & 1 && pDVar1->nLevelPrest == 0x2c9) {
              break;
            }

            pSearchRoom = pSearchRoom->pRoomExNext;
          }

          pDVar1->nFlags |= 2;
          pDVar1->nLevelPrest = 0x2e1;
          pDVar1->nPickedFile = -1;
          pSearchRoom = pLevel->pRoomExFirst;
          while (true) {
            if (!pSearchRoom) {
              Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x84c);
              exit(-1);
            }

            pDVar1 = pSearchRoom->pRoomExData.pRoomExDataPreset;
            if (~(pDVar1->nFlags >> 1) & 1 && pDVar1->nLevelPrest == 0x2ca) {
              break;
            }

            pSearchRoom = pSearchRoom->pRoomExNext;
          }

          pDVar1->nFlags |= 2;
          pDVar1->nLevelPrest = 0x2e2;
          pDVar1->nPickedFile = -1;
          ActualLevelGeneration(pLevel);
          Act3::Sewers::DRLGMAZE_ReplaceSewerRooms(pLevel);
          goto finish_level;
        }
      }

      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", (int32_t)(char*)Fog::Src::ErrorManager::GetInstructionPointer(), 0x849);
      exit(-1);
      case 0x20:
        /* Temples picker */ DRLGMAZE_BuildRoomGrid(2, pLevel);
      Act5::Temple::ReplaceRooms(pLevel);
      break;
      case 0x21:
        /* Ice caves */ eLevelId = pLevel->eD2LevelId;
      switch (eLevelId) {
        case LEVEL_FrozenRiver:
          {
            if (!pLevel->pRoomExFirst) {
              Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", (int32_t)(char*)Fog::Src::ErrorManager::GetInstructionPointer(), 0x85e);
              exit(-1);
            }

            nVariant = D2Client::Archive::UNIT_GetModuloFromSeed(&pRoomEx->pLevel->sSeed, 2);
            pFrozenRiverRoomData = pLevel->pRoomExFirst->pRoomExData.pRoomExDataPreset;
            pFrozenRiverRoomData->nFlags |= 2;
            pFrozenRiverRoomData->nLevelPrest = 0x40f - (uint32_t)(nVariant != 0);
            pFrozenRiverRoomData->nPickedFile = -1;
            break;
          }
        case LEVEL_DrifterCavern:
          {
            pDrifterCavernRoomData = pLevel->pRoomExFirst->pRoomExData.pRoomExDataPreset;
            pDrifterCavernRoomData->nFlags |= 2;
            pDrifterCavernRoomData->nLevelPrest = 0x410;
            pDrifterCavernRoomData->nPickedFile = -1;
            break;
          }
        case LEVEL_IcyCellar:
          {
            pIcyCellarRoomData = pLevel->pRoomExFirst->pRoomExData.pRoomExDataPreset;
            pIcyCellarRoomData->nFlags |= 2;
            pIcyCellarRoomData->nLevelPrest = 0x411;
            pIcyCellarRoomData->nPickedFile = -1;
            break;
          }
        default:
          {
            DRLGMAZE_BuildRoomGrid(2, pLevel);
            ActualLevelGeneration(pLevel);
            Act5::IceCaves::ReplaceRooms(pLevel);
          }
      }

      break;
      case 0x22:
        /* Worldstone */ GenerateWolrdstoneAndTombs(pLevel);
      ActualLevelGeneration(pLevel);
      Act5::Worldstone::PutRedNextLevelAreasInPlace(pLevel);
      break;
      case 0x23:
        SetupBaalChamber(pLevel);
    }

    finish_level:
    if (pLevel->eD2LevelId == 0x1c) {
      Act1::Barracks::DRLGMAZE_GenerateBarracksLayout(pLevel);
    } else if (pLevel->eD2LevelId == 0x6b) {
      Act4::RiverOfFlames::DRLGMAZE_GenerateRiverOfFlames(pLevel);
    } else {
      DRLGLEVEL_AdjustRoomCoordinates(pLevel);
    }
    ForAllButDenOfEvil(pLevel);
    pSearchRoom = pLevel->pRoomExFirst;
    BOOL BVar2 = bResult;
    while (pSearchRoom) {
      BOOL bResult2;
      pNextRoom = pSearchRoom->pRoomExNext;
      InitAllRoomsEx(pSearchRoom, pLevel);
      pSearchRoom = pNextRoom;
      BVar2 = bResult2;
    }

    return BVar2;
    Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", (int32_t)(char*)Fog::Src::ErrorManager::GetInstructionPointer(), 0x883);
    exit(-1);
}

void __fastcall DRLGMAZE_ResetMazeRecord(D2DrlgLevelStrc * pLevel, BOOL bKeepRecord) {
    if (bKeepRecord) {
      return;
    }

    pLevel->pDrlgLevelData.pTxtLvlMaze = 0;
}

} // namespace D2Common::Drlg::Maze